//! Differential corpus: the native applier must reach the state the app's
//! Source editor reached for the same seed and ops (`*.app.json`, generated by
//! apps/web `block-corpus.app-profile.source-controls.test.ts` from the
//! ai-editing worker's headless cases). Source skips a refused op and applies
//! the ops after it.
use crate::plugins_group_b::{
    CodeLanguageRequest, CodeToken, CodeTokenError, CodeTokenProvider, CodeTokenRequest, CodeTokens,
};
use crate::{EditorType, surface};
use lexical_model::*;
use serde_json::Value;
use std::collections::HashSet;

const TEXT_CORPUS: &str = include_str!("corpus/text.app.json");
const NEW_ID: &str = "<new>";

#[derive(serde::Deserialize)]
struct Entry {
    name: String,
    seed: Value,
    ops: Vec<Value>,
    state: Value,
    /// Ops Source reported and skipped; the ops after each still applied.
    refused: Vec<usize>,
}

fn editor() -> Editor {
    // The host mints ids for split-off nodes; Source `Doc` does the same.
    crate::node_ids::NodeIdPlugin::register(
        surface::preset_builder_with_mode(EditorType::MarkdownSync, EditorMode::ViewAttached)
            .extension_state(crate::NodeClock(std::sync::Arc::new(|| 1234))),
        &["root", "paragraph", "text", "listitem", "task-list"],
        None,
        [3; 32],
    )
    .build()
    .expect("surface")
}

fn load(editor: &mut Editor, state: &Value) {
    let parsed = editor
        .parse_editor_state_str(&state.to_string())
        .expect("seed parses");
    editor
        .set_editor_state(parsed, TagSet::default())
        .expect("seed loads");
}

fn export(editor: &Editor) -> Value {
    serde_json::to_value(editor.state().to_json().expect("export")).expect("json")
}

fn collect_ids(value: &Value, ids: &mut HashSet<String>) {
    match value {
        Value::Array(items) => items.iter().for_each(|item| collect_ids(item, ids)),
        Value::Object(map) => {
            for (key, child) in map {
                if key == "$" {
                    if let Some(Value::String(id)) = child.get("id") {
                        ids.insert(id.clone());
                    }
                } else {
                    collect_ids(child, ids);
                }
            }
        }
        _ => {}
    }
}

/// Ids an op minted are random on both sides; seed ids must survive verbatim.
fn stable_ids(value: &Value, seed: &HashSet<String>) -> Value {
    match value {
        Value::Array(items) => Value::Array(items.iter().map(|v| stable_ids(v, seed)).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(key, child)| {
                    if key == "$"
                        && let Value::Object(state) = child
                    {
                        let mut state = state.clone();
                        if let Some(Value::String(id)) = state.get("id")
                            && !seed.contains(id)
                        {
                            state.insert("id".into(), Value::String(NEW_ID.into()));
                        }
                        (key.clone(), Value::Object(state))
                    } else {
                        (key.clone(), stable_ids(child, seed))
                    }
                })
                .collect(),
        ),
        other => other.clone(),
    }
}

fn op_command(op: &Value, invocation: u32) -> Command {
    surface::decode_command(
        "group-c.ai-op",
        &serde_json::json!({ "op": op, "invocation": invocation }).to_string(),
        0,
        None,
    )
    .expect("decodes")
    .expect("group-c.ai-op")
}

/// Apply like the host: every op in order, each with its own token; a refused
/// op is recorded and the ones after it still apply. Returns the refused indices.
fn replay_ops(editor: &mut Editor, ops: &[Value]) -> Vec<usize> {
    let mut refused = Vec::new();
    for (index, op) in ops.iter().enumerate() {
        let invocation = u32::try_from(index + 1).expect("token");
        let (handled, commit) = editor
            .dispatch(&op_command(op, invocation))
            .expect("dispatch");
        if handled == Handled::No {
            // Exactly one refusal, carrying this input's own token.
            let own = refusals(&commit);
            assert_eq!(own.len(), 1, "op {index}: one refusal");
            assert_eq!(own[0]["invocation"], serde_json::json!(invocation));
            refused.push(index);
        }
    }
    refused
}

#[test]
fn text_ops_reach_the_source_doc_state() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    assert!(!corpus.is_empty());
    let mut failures = Vec::new();
    for entry in corpus {
        let mut seed_ids = HashSet::new();
        collect_ids(&entry.seed, &mut seed_ids);

        let mut native = editor();
        load(&mut native, &entry.seed);
        let refused = replay_ops(&mut native, &entry.ops);
        let actual = stable_ids(&export(&native), &seed_ids);

        // Compare against Source's result as the native model represents it.
        let mut source = editor();
        load(&mut source, &entry.state);
        let expected = stable_ids(&export(&source), &seed_ids);

        if refused != entry.refused || actual != expected {
            failures.push(format!(
                "{}: refused native {refused:?} source {:?}\n  native {actual}\n  source {expected}",
                entry.name, entry.refused
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn an_unknown_op_kind_is_refused_without_changing_the_document() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    let entry = &corpus[0];
    let mut native = editor();
    load(&mut native, &entry.seed);
    let before = export(&native);
    let op = serde_json::json!({ "kind": "notAnOp", "node": "s0000001" });
    let (handled, commit) = native.dispatch(&op_command(&op, 7)).expect("dispatch");
    assert_eq!(handled, Handled::No);
    assert_eq!(export(&native), before);
    assert_eq!(
        refusals(&commit),
        vec![serde_json::json!({ "cause": "unsupportedOp","invocation":7})]
    );
}

#[test]
fn selected_block_ids_are_the_touched_top_level_blocks_in_order() {
    let corpus: Vec<Entry> = serde_json::from_str(TEXT_CORPUS).expect("corpus");
    let entry = corpus
        .iter()
        .find(|entry| entry.name == "setText on each of two blocks")
        .expect("two-block seed");
    let mut native = editor();
    load(&mut native, &entry.seed);
    let blocks: Vec<NodeKey> = native.state().view().children(NodeKey::ROOT).collect();
    let texts: Vec<NodeKey> = blocks
        .iter()
        .filter_map(|block| native.state().view().first_child(*block))
        .collect();
    let ids = |editor: &Editor| {
        surface::query(
            "group-c.selected-block-ids",
            &Value::Null,
            0,
            editor.state(),
        )
        .expect("query")
        .expect("registered query")
    };
    // No range selection: Source resolves nothing.
    assert_eq!(ids(&native), serde_json::json!([]));
    native
        .update(|tx| {
            tx.set_selection(Some(Selection::Range(RangeSelection::new(
                Point::text(texts[0], Utf16Offset(2)),
                Point::text(texts[1], Utf16Offset(3)),
            ))))?;
            Ok(())
        })
        .expect("select across both blocks");
    let expected: Vec<Value> = entry
        .ops
        .iter()
        .map(|op| op.get("node").cloned().expect("op node"))
        .collect();
    assert_eq!(ids(&native), Value::Array(expected));
}

/// The host-encoded `group-c.ai-op-refused` payloads a commit carries.
fn refusals(commit: &Commit) -> Vec<Value> {
    commit
        .events
        .iter()
        .filter(|event| event.name() == "group-c.ai-op-refused")
        .map(|event| {
            surface::event_payload(event)
                .expect("encode")
                .expect("group C encodes its refusal")
        })
        .collect()
}

/// One paragraph `para0001` holding one plain text run `text0001` = "abc".
fn abc_editor() -> Editor {
    let mut native = editor();
    load(
        &mut native,
        &serde_json::json!({"root":{"type":"root","version":1,"direction":null,"format":"","indent":0,
            "$":{"id":"root0001"},
            "children":[{"type":"paragraph","version":1,"direction":null,"format":"","indent":0,
                "textFormat":0,"textStyle":"","$":{"id":"para0001"},
                "children":[{"type":"text","version":1,"detail":0,"format":0,"mode":"normal",
                    "style":"","text":"abc","$":{"id":"text0001"}}]}]}}),
    );
    native
}

fn text_of(editor: &Editor) -> String {
    editor.state().root_text_content().to_string()
}

#[test]
fn a_huge_remove_length_is_refused_without_overflow() {
    let mut native = abc_editor();
    let before = export(&native);
    // Source: Math.min(3, 1 + 1e100) removes to the end; native refuses the
    // out-of-domain length (corrupt model input, a named difference).
    let op = serde_json::json!({"kind":"removeText","node":"para0001","at":1,"len":1e100});
    let (handled, commit) = native.dispatch(&op_command(&op, 7)).expect("no panic");
    assert_eq!(handled, Handled::No);
    assert_eq!(export(&native), before);
    assert_eq!(
        refusals(&commit),
        vec![
            serde_json::json!({"cause":"invalidNumber","field":"len","problem":"aboveMaxSafeInteger","invocation":7})
        ]
    );

    // Each bound is safe, but the range end is not.
    let op = serde_json::json!({"kind":"removeText","node":"para0001",
        "at":9_007_199_254_740_991_u64,"len":1});
    let (handled, commit) = native.dispatch(&op_command(&op, 7)).expect("no panic");
    assert_eq!(handled, Handled::No);
    assert_eq!(export(&native), before);
    assert_eq!(
        refusals(&commit),
        vec![serde_json::json!({"cause":"rangeTooLarge","invocation":7})]
    );

    // Control: a safe range past the end clamps like Source slice.
    let op = serde_json::json!({"kind":"removeText","node":"para0001","at":1,"len":9_007_199_254_740_990_u64});
    let (handled, commit) = native.dispatch(&op_command(&op, 7)).expect("dispatch");
    assert_eq!(handled, Handled::Yes);
    assert!(refusals(&commit).is_empty());
    assert_eq!(text_of(&native), "a");
}

