#[test]
fn a_malformed_op_is_a_decode_error() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    // A supported kind with a missing field.
    assert!(decode(serde_json::json!({"op":{"kind":"setText","node":"text0001"}})).is_err());
    // A string where a number belongs.
    assert!(
        decode(
            serde_json::json!({"op":{"kind":"insertText","node":"text0001","at":"1","text":"x"}})
        )
        .is_err()
    );
    assert!(decode(serde_json::json!({"op":"setText"})).is_err());
    assert!(decode(serde_json::json!({"op":{"node":"text0001"}})).is_err());
}

#[test]
fn the_invocation_token_is_a_required_u32() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    let op = serde_json::json!({"kind":"setText","node":"text0001","text":"x"});
    assert!(decode(serde_json::json!({"op": op, "invocation": 1})).is_ok());
    assert!(decode(serde_json::json!({"op": op, "invocation": 4_294_967_295_u64})).is_ok());
    for bad in [
        serde_json::json!({"op": op}),
        serde_json::json!({"op": op, "invocation": -1}),
        serde_json::json!({"op": op, "invocation": 1.5}),
        serde_json::json!({"op": op, "invocation": 4_294_967_296_u64}),
        serde_json::json!({"op": op, "invocation": "1"}),
        serde_json::json!({"op": op, "invocation": null}),
    ] {
        assert!(decode(bad.clone()).is_err(), "{bad}");
    }
}

#[test]
fn the_ai_op_envelope_is_closed() {
    let decode = |json: Value| surface::decode_command("group-c.ai-op", &json.to_string(), 0, None);
    let op = serde_json::json!({"kind":"setText","node":"text0001","text":"x"});
    // A stale merge flag from an older host must not be ignored.
    for stale in [
        serde_json::json!(true),
        serde_json::json!(false),
        serde_json::json!(1),
    ] {
        assert!(decode(serde_json::json!({"op": op, "invocation": 1, "merge": stale})).is_err());
    }
    assert!(decode(serde_json::json!({"op": op, "invocation": 1, "extra": 0})).is_err());
}

#[test]
fn a_refusal_echoes_only_its_own_token() {
    let mut native = abc_editor();
    let op = serde_json::json!({"kind":"setText","node":"missing1","text":"x"});
    for token in [1_u32, 42, u32::MAX] {
        let (handled, commit) = native.dispatch(&op_command(&op, token)).expect("dispatch");
        assert_eq!(handled, Handled::No);
        assert_eq!(
            refusals(&commit),
            vec![serde_json::json!({"cause":"unknownNode","invocation":token})]
        );
    }
}

fn clear_selection_command(json: &str) -> crate::ModelResult<Option<Command>> {
    surface::decode_command("group-c.ai-edit-clear-selection", json, 0, None)
}

#[test]
fn the_clear_selection_payload_is_empty() {
    assert!(clear_selection_command("{}").expect("decodes").is_some());
    for bad in ["[]", "null", r#"{"x":1}"#, "1"] {
        assert!(clear_selection_command(bad).is_err(), "{bad}");
    }
}

#[test]
fn the_clear_selection_command_drops_the_selection_only() {
    // Source applyAiOps' first update, `$setSelection(null)`, runs even for no ops.
    let mut native = abc_editor();
    let text = native
        .state()
        .view()
        .first_child(
            native
                .state()
                .view()
                .first_child(NodeKey::ROOT)
                .expect("paragraph"),
        )
        .expect("text");
    native
        .update(|tx| {
            tx.set_selection(Some(Selection::Range(RangeSelection::new(
                Point::text(text, Utf16Offset(0)),
                Point::text(text, Utf16Offset(2)),
            ))))?;
            Ok(())
        })
        .expect("select ab");
    let before = export(&native);
    let command = clear_selection_command("{}")
        .expect("decodes")
        .expect("command");
    let (handled, commit) = native.dispatch(&command).expect("dispatch");
    assert_eq!(handled, Handled::Yes);
    assert_eq!(native.state().selection(), None);
    assert!(commit.selection_changed);
    assert_eq!(export(&native), before);
    assert!(commit.tags.iter().next().is_none());
    // Already clear: still handled, still no document change.
    let (handled, _) = native.dispatch(&command).expect("dispatch");
    assert_eq!(handled, Handled::Yes);
    assert_eq!(export(&native), before);
}

const BLOCK_CORPUS: &str = include_str!("corpus/blocks.app.json");

/// Every node type Source `nodeIdPlugin` gives an id in the block corpus.
const BLOCK_ID_CLASSES: [&str; 14] = [
    "root",
    "paragraph",
    "text",
    "heading",
    "quote",
    "custom-code",
    "code-highlight",
    "equation",
    "horizontalrule",
    "listitem",
    "task-list",
    "table",
    "tablerow",
    "tablecell",
];

#[derive(serde::Deserialize)]
struct BlockEntry {
    name: String,
    seed: Value,
    ops: Vec<Value>,
    /// Source's load of `seed`: what the native import must produce.
    loaded: Value,
    state: Value,
    /// Ops Source reported and skipped; the ops after each still applied.
    refused: Vec<usize>,
    refs: Vec<String>,
    /// Source's own load of `state`, recorded only where it differs.
    #[serde(default)]
    reloaded: Option<Value>,
}

fn block_editor() -> Editor {
    crate::node_ids::NodeIdPlugin::register(
        surface::preset_builder_with_mode(EditorType::MarkdownSync, EditorMode::ViewAttached)
            .extension_state(crate::NodeClock(std::sync::Arc::new(|| 1234))),
        &BLOCK_ID_CLASSES,
        None,
        [5; 32],
    )
    .build()
    .expect("surface")
}

/// TEST-ONLY replay of the Prism tokens the Source oracle recorded for each
/// code block, keyed by (language, text). It is not a tokenizer: with it the
/// corpus checks native retyping and token application, not Prism parity
/// (that is the stage browser run's, with the app's real Prism).
struct SourcePrismReplay(std::collections::HashMap<(String, String), Vec<CodeToken>>);

impl SourcePrismReplay {
    /// Every code block in `state`, as (language, text).
    fn code_blocks(state: &Value) -> Vec<(String, String)> {
        fn walk(value: &Value, out: &mut Vec<(String, String)>) {
            let Some(children) = value.get("children").and_then(Value::as_array) else {
                return;
            };
            if matches!(value["type"].as_str(), Some("custom-code" | "code")) {
                let text = children
                    .iter()
                    .map(|child| match child["type"].as_str() {
                        Some("linebreak") => "\n",
                        Some("tab") => "\t",
                        _ => child["text"].as_str().unwrap_or_default(),
                    })
                    .collect();
                out.push((
                    value["language"].as_str().unwrap_or_default().to_owned(),
                    text,
                ));
            }
            for child in children {
                walk(child, out);
            }
        }
        let mut out = Vec::new();
        walk(&state["root"], &mut out);
        out
    }

    fn from_corpus(corpus: &[BlockEntry]) -> Self {
        fn walk(
            value: &Value,
            out: &mut std::collections::HashMap<(String, String), Vec<CodeToken>>,
        ) {
            let Some(children) = value.get("children").and_then(Value::as_array) else {
                return;
            };
            if matches!(value["type"].as_str(), Some("custom-code" | "code")) {
                let language = value["language"].as_str().unwrap_or_default().to_owned();
                let mut text = String::new();
                let mut tokens = Vec::new();
                for child in children {
                    match child["type"].as_str() {
                        Some("linebreak") => {
                            text.push('\n');
                            tokens.push(CodeToken::LineBreak);
                        }
                        Some("tab") => {
                            text.push('\t');
                            tokens.push(CodeToken::Tab);
                        }
                        _ => {
                            let run = child["text"].as_str().unwrap_or_default();
                            text.push_str(run);
                            tokens.push(CodeToken::Text {
                                text: run.to_owned(),
                                highlight_type: child["highlightType"].as_str().map(str::to_owned),
                            });
                        }
                    }
                }
                out.insert((language, text), tokens);
            }
            for child in children {
                walk(child, out);
            }
        }
        let mut recorded = std::collections::HashMap::new();
        for entry in corpus {
            walk(&entry.state["root"], &mut recorded);
        }
        Self(recorded)
    }
}

impl CodeTokenProvider for SourcePrismReplay {
    fn is_loaded(&self, request: &CodeLanguageRequest<'_>) -> Result<bool, CodeTokenError> {
        Ok(self
            .0
            .keys()
            .any(|(language, _)| language == request.language))
    }
    fn tokenize(&self, request: &CodeTokenRequest<'_>) -> Result<Vec<CodeToken>, CodeTokenError> {
        // Texts Source never tokenized (intermediate states) stay one plain run.
        Ok(self
            .0
            .get(&(request.language.to_owned(), request.text.to_owned()))
            .cloned()
            .unwrap_or_else(|| {
                if request.text.is_empty() {
                    Vec::new()
                } else {
                    vec![CodeToken::Text {
                        text: request.text.to_owned(),
                        highlight_type: None,
                    }]
                }
            }))
    }
}

/// The block editor with the recorded Source Prism tokens installed.
fn block_editor_replaying(replay: &std::sync::Arc<SourcePrismReplay>) -> Editor {
    let provider: std::sync::Arc<dyn CodeTokenProvider> = replay.clone();
    crate::node_ids::NodeIdPlugin::register(
        surface::preset_builder_with_mode_and_tokens(
            EditorType::MarkdownSync,
            EditorMode::ViewAttached,
            CodeTokens::new(provider, "source-prism-replay"),
        )
        .extension_state(crate::NodeClock(std::sync::Arc::new(|| 1234))),
        &BLOCK_ID_CLASSES,
        None,
        [5; 32],
    )
    .build()
    .expect("surface")
}

/// Seed ids and op refs stay verbatim; every other id is renamed `<newN>` in
/// document order, so freshly minted ids compare one to one, not as one bucket.
fn minted_bijection(value: &Value, kept: &HashSet<String>) -> Value {
    fn walk(
        value: &Value,
        kept: &HashSet<String>,
        names: &mut std::collections::HashMap<String, String>,
    ) -> Value {
        match value {
            Value::Array(items) => {
                Value::Array(items.iter().map(|v| walk(v, kept, names)).collect())
            }
            Value::Object(map) => {
                let mut out = serde_json::Map::new();
                // Own id first, then children, so numbering follows document order.
                if let Some(Value::Object(state)) = map.get("$") {
                    let mut state = state.clone();
                    if let Some(Value::String(id)) = state.get("id")
                        && !kept.contains(id)
                    {
                        let next = format!("<new{}>", names.len());
                        let name = names.entry(id.clone()).or_insert(next).clone();
                        state.insert("id".into(), Value::String(name));
                    }
                    out.insert("$".into(), Value::Object(state));
                }
                for (key, child) in map {
                    if key != "$" {
                        out.insert(key.clone(), walk(child, kept, names));
                    }
                }
                Value::Object(out)
            }
            other => other.clone(),
        }
    }
    walk(value, kept, &mut std::collections::HashMap::new())
}

/// Every id in document order, duplicates kept.
fn id_list(value: &Value, ids: &mut Vec<String>) {
    match value {
        Value::Array(items) => items.iter().for_each(|item| id_list(item, ids)),
        Value::Object(map) => {
            if let Some(Value::String(id)) = map.get("$").and_then(|state| state.get("id")) {
                ids.push(id.clone());
            }
            for (key, child) in map {
                if key != "$" {
                    id_list(child, ids);
                }
            }
        }
        _ => {}
    }
}

/// Known parity gap (board E15, phase L list load normalization): reloading Source's
/// un-normalized paragraph-in-list state, Source's list transform renumbers the
/// wrapped items and native keeps their values. Native's current values are
/// asserted, so the phase L fix flips this pin. (entry, native, Source)
const KNOWN_RELOAD_VALUES: &[(&str, &[i64], &[i64])] = &[(
    "insertNode paragraph before a list item",
    &[1, 1, 2],
    &[1, 2, 3],
)];

/// Every listitem `value` in document order.
fn listitem_values(value: &Value) -> Vec<i64> {
    let mut values = Vec::new();
    fn walk(value: &Value, values: &mut Vec<i64>) {
        match value {
            Value::Array(items) => items.iter().for_each(|item| walk(item, values)),
            Value::Object(map) => {
                if map.get("type") == Some(&Value::String("listitem".into()))
                    && let Some(number) = map.get("value").and_then(Value::as_i64)
                {
                    values.push(number);
                }
                map.iter()
                    .filter(|(key, _)| *key != "$")
                    .for_each(|(_, child)| walk(child, values));
            }
            _ => {}
        }
    }
    walk(value, &mut values);
    values
}

/// Overwrite listitem `value`s in document order.
fn set_listitem_values(value: &mut Value, numbers: &mut dyn Iterator<Item = i64>) {
    match value {
        Value::Array(items) => items
            .iter_mut()
            .for_each(|item| set_listitem_values(item, numbers)),
        Value::Object(map) => {
            if map.get("type") == Some(&Value::String("listitem".into()))
                && map.contains_key("value")
                && let Some(number) = numbers.next()
            {
                map.insert("value".into(), Value::from(number));
            }
            map.iter_mut()
                .filter(|(key, _)| *key != "$")
                .for_each(|(_, child)| set_listitem_values(child, numbers));
        }
        _ => {}
    }
}

/// Oracle control: the raw Source JSON must survive a native import and export
/// unchanged, or the parity comparison below would compare a native projection.
#[test]
fn native_import_matches_the_app_source_load() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    for (name, ..) in KNOWN_RELOAD_VALUES {
        assert!(
            corpus
                .iter()
                .any(|entry| entry.name == *name && entry.reloaded.is_some()),
            "known reload difference {name} no longer reloads differently"
        );
    }
    let mut deltas = Vec::new();
    for entry in &corpus {
        // Native loads a stored state the way the app's Source editor does.
        for (label, raw, expected) in [
            ("seed", &entry.seed, &entry.loaded),
            ("loaded", &entry.loaded, &entry.loaded),
            (
                "state",
                &entry.state,
                entry.reloaded.as_ref().unwrap_or(&entry.state),
            ),
        ] {
            let mut editor = block_editor();
            load(&mut editor, raw);
            let mut exported = export(&editor);
            let mut expected = expected.clone();
            if label == "state" && entry.reloaded.is_some() {
                // Ids both sides mint while reloading compare one to one; the
                // stored ids and op refs stay verbatim.
                let mut stored = Vec::new();
                id_list(raw, &mut stored);
                let kept: HashSet<String> = stored.into_iter().collect();
                exported = minted_bijection(&exported, &kept);
                expected = minted_bijection(&expected, &kept);
                if let Some((native, source)) = KNOWN_RELOAD_VALUES
                    .iter()
                    .find(|(name, ..)| *name == entry.name)
                    .map(|(_, native, source)| (native, source))
                {
                    assert_eq!(listitem_values(&exported), *native, "{}", entry.name);
                    assert_eq!(listitem_values(&expected), *source, "{}", entry.name);
                    set_listitem_values(&mut exported, &mut source.iter().copied());
                }
            }
            if exported != expected {
                deltas.push(format!(
                    "{} [{label}]\n  source {expected}\n  native {exported}",
                    entry.name
                ));
            }
        }
    }
    assert!(
        deltas.is_empty(),
        "{} projection deltas:\n{}",
        deltas.len(),
        deltas.join("\n")
    );
}

/// Per-case outcome against the raw Source state. Cases Source applies fully are
/// positive-support checks; cases Source stops at op k are refusal-equivalence
/// checks (failedAt only, not typed-cause parity, which has its own tests).
#[test]
fn block_ops_reach_the_source_doc_state() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    assert!(!corpus.is_empty());
    let replay = std::sync::Arc::new(SourcePrismReplay::from_corpus(&corpus));
    let mut rows = Vec::new();
    let mut failed = 0;
    for entry in corpus {
        let class = if entry.refused.is_empty() {
            "positive".to_string()
        } else {
            format!("refused{:?}", entry.refused)
        };
        let mut kept = HashSet::new();
        collect_ids(&entry.seed, &mut kept);
        let refs: HashSet<String> = entry.refs.iter().cloned().collect();

        let mut native = block_editor_replaying(&replay);
        load(&mut native, &entry.seed);
        let refused = replay_ops(&mut native, &entry.ops);
        let exported = export(&native);

        // Lineage on raw values, before any renaming.
        let mut problems = Vec::new();
        for (side, value) in [("native", &exported), ("source", &entry.state)] {
            let mut ids = Vec::new();
            id_list(value, &mut ids);
            let unique: HashSet<&String> = ids.iter().collect();
            if unique.len() != ids.len() {
                problems.push(format!("{side} has duplicate ids"));
            }
        }
        let (mut native_ids, mut source_ids) = (Vec::new(), Vec::new());
        id_list(&exported, &mut native_ids);
        id_list(&entry.state, &mut source_ids);
        let native_set: HashSet<&String> = native_ids.iter().collect();
        let source_set: HashSet<&String> = source_ids.iter().collect();
        for id in kept.iter().chain(refs.iter()) {
            if native_set.contains(id) != source_set.contains(id) {
                problems.push(format!(
                    "id {id}: native {} source {}",
                    native_set.contains(id),
                    source_set.contains(id)
                ));
            }
        }
        if refused != entry.refused {
            problems.push(format!(
                "refused native {refused:?} source {:?}",
                entry.refused
            ));
        }
        // The plain-run fallback may cover intermediate states only: every
        // final code block must be one Source tokenized.
        for (language, text) in SourcePrismReplay::code_blocks(&exported) {
            if !replay.0.contains_key(&(language.clone(), text.clone())) {
                problems.push(format!(
                    "code {language:?} {text:?} was never tokenized by Source"
                ));
            }
        }
        let mut stable = kept.clone();
        stable.extend(refs);
        let actual = minted_bijection(&exported, &stable);
        let expected = minted_bijection(&entry.state, &stable);
        if actual != expected {
            problems.push(format!("state\n    native {actual}\n    source {expected}"));
        }
        let outcome = if problems.is_empty() {
            "match".to_string()
        } else {
            failed += 1;
            format!("MISMATCH: {}", problems.join("; "))
        };
        rows.push(format!("{class:<11} {}: {outcome}", entry.name));
    }
    assert!(
        failed == 0,
        "{failed} of {} cases differ:\n{}",
        rows.len(),
        rows.join("\n")
    );
}

const SELECTION_CORPUS: &str = include_str!("corpus/selection.json");

/// Node key at a child-index path from the root.
fn at_path(editor: &Editor, path: &[u64]) -> NodeKey {
    let view = editor.state().view();
    let mut key = NodeKey::ROOT;
    for index in path {
        let index = usize::try_from(*index).expect("index");
        key = view.children(key).nth(index).expect("path exists");
    }
    key
}

fn path_of(value: &Value) -> Vec<u64> {
    value
        .as_array()
        .expect("path")
        .iter()
        .map(|i| i.as_u64().expect("index"))
        .collect()
}

/// Source MarkdownPopup ids for stored table and in-table range selections,
/// transcribed from the live OFF capture named in the corpus `evidence`.
#[test]
fn selected_block_ids_match_source_for_table_selections() {
    let corpus: Value = serde_json::from_str(SELECTION_CORPUS).expect("corpus");
    let mut rows = Vec::new();
    let mut failed = 0;
    for case in corpus["cases"].as_array().expect("cases") {
        let mut native = block_editor();
        load(&mut native, &corpus["seed"]);
        let selection = &case["selection"];
        let chosen = match selection["kind"].as_str() {
            Some("table") => {
                let anchor = at_path(&native, &path_of(&selection["anchor"]));
                let focus = at_path(&native, &path_of(&selection["focus"]));
                let table = at_path(&native, &path_of(&selection["anchor"])[..1]);
                Selection::Table(TableSelection::new(table, anchor, focus))
            }
            _ => {
                let point = |side: &Value| {
                    let key = at_path(&native, &path_of(&side["path"]));
                    let offset =
                        u32::try_from(side["offset"].as_u64().expect("offset")).expect("u32");
                    Point::text(key, Utf16Offset(offset))
                };
                Selection::Range(RangeSelection::new(
                    point(&selection["anchor"]),
                    point(&selection["focus"]),
                ))
            }
        };
        native
            .update(|tx| {
                tx.set_selection(Some(chosen))?;
                Ok(())
            })
            .expect("select");
        let expected: Vec<Value> = case["expected"]
            .as_array()
            .expect("expected")
            .iter()
            .map(|path| {
                let key = at_path(&native, &path_of(path));
                let id = crate::node_ids::get_id(native.state().view(), key)
                    .expect("id read")
                    .expect("seed node has an id");
                Value::String(id.into())
            })
            .collect();
        let actual = surface::query(
            "group-c.selected-block-ids",
            &Value::Null,
            0,
            native.state(),
        )
        .expect("query")
        .expect("registered query");
        let name = case["name"].as_str().unwrap_or("?");
        if actual == Value::Array(expected.clone()) {
            rows.push(format!("match    {name}"));
        } else {
            failed += 1;
            rows.push(format!(
                "MISMATCH {name}\n    native {actual}\n    source {}",
                Value::Array(expected)
            ));
        }
    }
    assert!(failed == 0, "{failed} cases differ:\n{}", rows.join("\n"));
}

/// B1a corners the Source corpus does not reach; each is refused before any
/// write, where Source's Lexical calls throw inside its transaction.
#[test]
fn node_ops_refuse_the_root_and_moves_beside_themselves() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    let entry = corpus
        .iter()
        .find(|entry| entry.name == "moveNode the last block to the front")
        .expect("three-paragraph seed");
    let root = entry.loaded["root"]["$"]["id"].as_str().expect("root id");
    for (op, cause) in [
        // The root is not addressable by id, as for the text ops; Source's
        // Lexical refuses to remove, move or place beside it.
        (
            serde_json::json!({"kind":"removeNode","node":root}),
            "unknownNode",
        ),
        (
            serde_json::json!({"kind":"moveNode","node":root,"at":{"appendToRoot":true}}),
            "unknownNode",
        ),
        // A target inside the moved block (its own text climbs to the block).
        (
            serde_json::json!({"kind":"moveNode","node":"s0000005","at":{"after":"s0000004"}}),
            "wrongTarget",
        ),
        (
            serde_json::json!({"kind":"moveNode","node":"s0000005","at":{"before":"s0000005"}}),
            "wrongTarget",
        ),
        (
            serde_json::json!({"kind":"moveNode","node":"s0000005","at":{"after":root}}),
            "unknownNode",
        ),
        (
            serde_json::json!({"kind":"moveNode","node":"s0000005","at":{"after":"missing1"}}),
            "unknownNode",
        ),
    ] {
        let mut native = block_editor();
        load(&mut native, &entry.loaded);
        let before = export(&native);
        let (handled, commit) = native.dispatch(&op_command(&op, 7)).expect("dispatch");
        assert_eq!(handled, Handled::No, "{op}");
        assert_eq!(export(&native), before, "{op}");
        assert_eq!(
            refusals(&commit),
            vec![serde_json::json!({"cause": cause, "invocation": 7})],
            "{op}"
        );
    }
}

#[test]
fn a_move_position_takes_source_key_order() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    let entry = corpus
        .iter()
        .find(|entry| entry.name == "moveNode the last block to the front")
        .expect("three-paragraph seed");
    let order = |native: &Editor| -> Vec<String> {
        let view = native.state().view();
        view.children(NodeKey::ROOT)
            .map(|key| {
                crate::node_ids::get_id(view, key)
                    .expect("id")
                    .map(|id| id.to_string())
                    .unwrap_or_default()
            })
            .collect()
    };
    for (at, expected) in [
        // `after` wins over `before`, `before` over `appendToRoot`.
        (
            serde_json::json!({"after":"s0000001","before":"s0000003"}),
            ["s0000001", "s0000005", "s0000003"],
        ),
        (
            serde_json::json!({"before":"s0000003","appendToRoot":true}),
            ["s0000001", "s0000005", "s0000003"],
        ),
        // Any other object prepends, as Source `place` does.
        (serde_json::json!({}), ["s0000005", "s0000001", "s0000003"]),
        (
            serde_json::json!({"prependToRoot":true}),
            ["s0000005", "s0000001", "s0000003"],
        ),
    ] {
        let mut native = block_editor();
        load(&mut native, &entry.loaded);
        let op = serde_json::json!({"kind":"moveNode","node":"s0000005","at":at});
        let (handled, _) = native.dispatch(&op_command(&op, 7)).expect("dispatch");
        assert_eq!(handled, Handled::Yes, "{op}");
        assert_eq!(order(&native), expected, "{op}");
    }
}

/// Drift guard: the move planner predicts what a removal detaches with a copy
/// of `$removeNode`, `ListItemNode.remove` and `merge_lists`. For every corpus
/// case that removes or moves a node, run the real removal and require the
/// prediction to name exactly the nodes left unattached.
#[test]
fn the_removal_prediction_matches_the_real_removal() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    let mut checked = 0;
    for entry in &corpus {
        let Some(op) = entry.ops.first() else {
            continue;
        };
        let (Some(kind), Some(Value::String(node))) = (op["kind"].as_str(), op.get("node")) else {
            continue;
        };
        if kind != "removeNode" && kind != "moveNode" {
            continue;
        }
        let mut native = block_editor();
        load(&mut native, &entry.loaded);
        let mut outcome = None;
        native
            .update(|tx| {
                let resolved = if kind == "moveNode" {
                    super::nodes::anchor(tx, node)?
                } else {
                    super::by_id(tx, node)?
                };
                let Ok(key) = resolved else {
                    return Ok(());
                };
                let view = tx.view();
                let before: Vec<NodeKey> =
                    view.descendants(view.root()).map(|(key, _)| key).collect();
                let detached = super::nodes::detached_by_remove(tx, key);
                let predicted: Vec<NodeKey> = before
                    .iter()
                    .copied()
                    .filter(|key| detached.contains(tx.view(), *key))
                    .collect();
                tx.remove(key, false)?;
                let after = tx.view();
                let actual: Vec<NodeKey> = before
                    .iter()
                    .copied()
                    .filter(|key| !after.has_ancestor(*key, NodeKey::ROOT))
                    .collect();
                outcome = Some((predicted, actual));
                Ok(())
            })
            .expect("remove");
        let Some((predicted, actual)) = outcome else {
            continue;
        };
        assert_eq!(predicted, actual, "{}", entry.name);
        checked += 1;
    }
    // Every removeNode/moveNode case whose node resolves.
    assert!(checked >= 11, "checked {checked}");
}

/// Source `nextVersionId`: a retyped block's id is the old id with `~v1`, or
/// the next version when already versioned. As in the app, whose nodeIdPlugin
/// drops a destroyed node's id when the retype commits, the old id no longer
/// resolves afterwards.
#[test]
fn a_retyped_block_takes_the_next_version_id() {
    let corpus: Vec<BlockEntry> = serde_json::from_str(BLOCK_CORPUS).expect("corpus");
    let entry = corpus
        .iter()
        .find(|entry| entry.name == "setBlockType paragraph to heading 3")
        .expect("paragraph seed");
    let mut native = block_editor();
    load(&mut native, &entry.loaded);
    let first_id = |native: &Editor| -> String {
        let view = native.state().view();
        let key = view.first_child(NodeKey::ROOT).expect("block");
        crate::node_ids::get_id(view, key)
            .expect("id")
            .map(|id| id.to_string())
            .unwrap_or_default()
    };
    let retype = |native: &mut Editor, node: &str, block: Value| {
        let mut op = serde_json::json!({"kind":"setBlockType","node":node});
        for (key, value) in block.as_object().expect("block fields") {
            op[key] = value.clone();
        }
        native.dispatch(&op_command(&op, 7)).expect("dispatch")
    };
    let (handled, _) = retype(
        &mut native,
        "s0000001",
        serde_json::json!({"block":"heading","level":3}),
    );
    assert_eq!(handled, Handled::Yes);
    assert_eq!(first_id(&native), "s0000001~v1");
    let (handled, commit) = retype(
        &mut native,
        "s0000001",
        serde_json::json!({"block":"quote"}),
    );
    assert_eq!(handled, Handled::No);
    assert_eq!(
        refusals(&commit),
        vec![serde_json::json!({"cause":"unknownNode","invocation":7})]
    );
    let (handled, _) = retype(
        &mut native,
        "s0000001~v1",
        serde_json::json!({"block":"quote"}),
    );
    assert_eq!(handled, Handled::Yes);
    assert_eq!(first_id(&native), "s0000001~v2");
}

/// Lexical `ListItemNode.setIndent` throws on a negative indent: native refuses
